Lemma mslot_inj a a' k k' : snd a mod PGSZ = 0 -> snd a' mod PGSZ = 0 -> 0 <= k < NSLOTS -> 0 <= k' < NSLOTS ->
  mslot a k = mslot a' k' -> a = a' /\ k = k'.
