Definition gm (bh : aptr * ghdr) : aptr := default (0%N, 0) (g_meta (snd bh)).
Definition ne_b (bh : aptr * ghdr) : bool := negb (fmask (MR st (gm bh)) =? mask_upto (m_last_idx (MR st (gm bh)))).

Lemma GL_in b h : In (b, h) GL <-> s_groups st !! b = Some h.
