Definition wgr (kr : N * region) : Z := mmap_len (r_len (snd kr)).

(* [comment removed for export] *)
Theorem group_bytes_bound : zsum (map wgr GR) <= zsum (map (fun e => csz (snd e)) SZ) + 32 * 2 ^ 20.
Proof.
