Record SCAL (s s' : mstate) : Prop := mkSC {
  sc_metas : s_metas s' = s_metas s;
  sc_groups : s_groups s' = s_groups s;
  sc_slots : s_slots s' = s_slots s;
  sc_heads : forall h, get_head s' h = get_head s h;
  sc_mfr : MFR s s'
}.

